function isPastEditWindow(comment: Comment): boolean {
  // The window is fixed at the original posting; later edits never reset it.
  const posted = new Date(comment.createdAt).getTime();
  return Date.now() - posted > EDIT_WINDOW_MS;
}

/**
 * Union of the ids the client already resolved (optimistic UI) and the ones
 * parsed out of the body server-side. The server list wins on disagreement.
 * Every active member of the org is scanned, however many pages that takes,
 * so a long-standing member is never dropped by a lookup page size. The
 * comment's own author never mentions themself.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
  authorId: UserId,
): Promise<readonly UserId[]> {
  const members: MemberWithUser[] = [];
  let cursor: string | null = null;
  do {
    const page = await memberRepo.listMembers({
      orgId,
      limit: MENTION_LOOKUP_PAGE_SIZE,
      cursor,
    });
    members.push(...page.items);
    cursor = page.nextCursor;
  } while (cursor !== null);

  const resolved = resolveMentions(body, members);
  const known = new Set(members.map((member) => member.userId));

  return [
    ...new Set(
      [...resolved, ...clientProvided.filter((id) => known.has(id))].filter(
        (id) => id !== authorId,
      ),
    ),
  ];
}

