  const childrenByParent = new Map<string, CommentWithAuthor[]>();
  for (const comment of decorated) {
    if (comment.parentId === null) continue;
    const bucket = childrenByParent.get(comment.parentId) ?? [];
    bucket.push(comment);
    childrenByParent.set(comment.parentId, bucket);
  }

  function descendantIds(rootId: string): Set<string> {
    const result = new Set<string>();
    const stack = [rootId];
    while (stack.length > 0) {
      const id = stack.pop();
      if (id === undefined) continue;
      for (const child of childrenByParent.get(id) ?? []) {
        if (!result.has(child.id)) {
          result.add(child.id);
          stack.push(child.id);
        }
      }
    }
    return result;
  }

  // A deleted comment keeps its place as a placeholder: no text, but its
  // replies (direct or through other replies) stay anchored beneath it.
  function redact(comment: CommentWithAuthor): CommentWithAuthor {
    return comment.archivedAt === null ? comment : { ...comment, body: "" };
  }

  return decorated
    .filter((comment) => comment.parentId === null)
    .map((comment) => {
      const ids = descendantIds(comment.id);
      return {
        comment: redact(comment),
        replies: decorated
          .filter((candidate) => ids.has(candidate.id))
          .map(redact),
      };
    });
}

